/*
 * timestamp.c
 *		Functions for the PostgreSQL date/time types.
 *
 * Portions Copyright (c) 1996-2024, PostgreSQL Global Development Group
 * Portions Copyright (c) 1994, Regents of the University of California
 *
 * IDENTIFICATION
 *	  src/backend/utils/adt/timestamp.c
 *
 *-------------------------------------------------------------------------
 */

#include "postgres.h"

#include <ctype.h>
#include <float.h>
#include <limits.h>
#include <math.h>
#include <time.h>

#include "access/hash.h"
#include "catalog/pg_type.h"
#include "common/int.h"
#include "common/timezone.h"
#include "funcapi.h"
#include "lib/stringinfo.h"
#include "libpq/pqformat.h"
#include "miscadmin.h"
#include "nodes/nodeFuncs.h"
#include "parser/scansup.h"
#include "utils/array.h"
#include "utils/builtins.h"
#include "utils/date.h"
#include "utils/datetime.h"
#include "utils/numeric.h"
#include "utils/sortsupport.h"
#include "utils/timestamp.h"
#include "utils/tzparser.h"

/* Truncation precision for timestamp */
typedef enum
{
	TimestampTruncUnit,
	TimestampDateTruncUnit
} TimestampTruncUnit;

/* Truncation units */
static const char * const trunc_units[] = {
	"microseconds",
	"milliseconds",
	"second",
	"minute",
	"hour",
	"day",
	"week",
	"month",
	"year",
	"decade",
	"century",
	"millennium"
};

static const int trunc_values[] = {
	6,			/* microseconds */
	3,			/* milliseconds */
	0,			/* second */
	1,			/* minute */
	2,			/* hour */
	3,			/* day */
	3,			/* week */
	4,			/* month */
	5,			/* year */
	6,			/* decade */
	7,			/* century */
	8			/* millennium */
};

/*
 * date_trunc()
 * Truncate timestamp to specified precision.
 */
Datum
date_trunc(PG_FUNCTION_ARGS)
{
	text	   *prec_text = PG_GETARG_TEXT_PP(0);
	Datum		timestamp_val;
	Timestamp	result;
	struct pg_tm tm;
	fsec_t		fsec;
	int			tz;
	char	   *prec;
	int			i;

	/* Check for NULL inputs */
	if (PG_ARGISNULL(0) || PG_ARGISNULL(1))
		PG_RETURN_NULL();

	/* Convert precision text to C string */
	prec = text_to_cstring(prec_text);

	/* Normalize precision string (lowercase, trim whitespace) */
	for (i = 0; prec[i]; i++)
		prec[i] = tolower((unsigned char) prec[i]);

	/* Remove trailing whitespace */
	i = strlen(prec);
	while (i > 0 && isspace((unsigned char) prec[i - 1]))
		prec[--i] = '\0';

	/* Find matching precision unit */
	i = 0;
	while (i < lengthof(trunc_units))
	{
		if (strcmp(prec, trunc_units[i]) == 0)
			break;
		i++;
	}

	/* Check if precision unit was found */
	if (i >= lengthof(trunc_units))
		ereport(ERROR,
				(errcode(ERRCODE_INVALID_PARAMETER_VALUE),
				 errmsg("invalid type name \"%s\"", prec),
				 errdetail("Valid units are: microseconds, milliseconds, second, minute, hour, day, week, month, year, decade, century, millennium.")));

	/* Get timestamp value */
	timestamp_val = PG_GETARG_DATUM(1);

	/* Convert timestamp to pg_tm structure */
	if (timestamp2tm(timestamp_val, NULL, &tm, &fsec, NULL, NULL) != 0)
		ereport(ERROR,
				(errcode(ERRCODE_DATETIME_VALUE_OUT_OF_RANGE),
				 errmsg("timestamp out of range")));

	/* Truncate based on precision */
	switch (i)
	{
		case 0:						/* microseconds */
			/* No truncation needed, fsec is already in microseconds */
			break;
		case 1:						/* milliseconds */
			fsec = (fsec_t) ((int64) (fsec * 1000)) / 1000.0;
			break;
		case 2:						/* second */
			fsec = 0;
			break;
		case 3:						/* minute */
			tm.tm_sec = 0;
			fsec = 0;
			break;
		case 4:						/* hour */
			tm.tm_min = 0;
			tm.tm_sec = 0;
			fsec = 0;
			break;
		case 5:						/* day */
			tm.tm_hour = 0;
			tm.tm_min = 0;
			tm.tm_sec = 0;
			fsec = 0;
			break;
		case 6:						/* week */
			{
				int			wday = tm.tm_wday;

				/* Adjust to Monday as first day of week */
				tm.tm_mday -= (wday + 6) % 7;
				tm.tm_hour = 0;
				tm.tm_min = 0;
				tm.tm_sec = 0;
				fsec = 0;
			}
			break;
		case 7:						/* month */
			tm.tm_mday = 1;
			tm.tm_hour = 0;
			tm.tm_min = 0;
			tm.tm_sec = 0;
			fsec = 0;
			break;
		case 8:						/* year */
			tm.tm_mon = 1;
			tm.tm_mday = 1;
			tm.tm_hour = 0;
			tm.tm_min = 0;
			tm.tm_sec = 0;
			fsec = 0;
			break;
		case 9:						/* decade */
			tm.tm_year = (tm.tm_year / 10) * 10;
			tm.tm_mon = 1;
			tm.tm_mday = 1;
			tm.tm_hour = 0;
			tm.tm_min = 0;
			tm.tm_sec = 0;
			fsec = 0;
			break;
		case 10:					/* century */
			tm.tm_year = (tm.tm_year / 100) * 100;
			tm.tm_mon = 1;
			tm.tm_mday = 1;
			tm.tm_hour = 0;
			tm.tm_min = 0;
			tm.tm_sec = 0;
			fsec = 0;
			break;
		case 11:					/* millennium */
			tm.tm_year = (tm.tm_year / 1000) * 1000;
			tm.tm_mon = 1;
			tm.tm_mday = 1;
			tm.tm_hour = 0;
			tm.tm_min = 0;
			tm.tm_sec = 0;
			fsec = 0;
			break;
	}

	/* Convert back to timestamp */
	if (tm2timestamp(&tm, fsec, NULL, &result) != 0)
		ereport(ERROR,
				(errcode(ERRCODE_DATETIME_VALUE_OUT_OF_RANGE),
				 errmsg("timestamp out of range")));

	PG_RETURN_TIMESTAMP(result);
}

