/* Truncation units */
static const char * const trunc_units[] = {
        "microseconds",
        "milliseconds",
        "second",
        "minute",
        "hour",
        "day",
        "week",
        "month",
        "year",
        "decade",
        "century",
        "millennium"
};

/*
 * date_trunc()
 * Truncate timestamp to specified precision.
 */
Datum
date_trunc(PG_FUNCTION_ARGS)
{
        text       *prec_text = PG_GETARG_TEXT_PP(0);
        Datum           timestamp_val;
        Timestamp       result;
        struct pg_tm tm;
        fsec_t          fsec;
        int                     tz;
        char       *prec;
        int                     i;

        /* Check for NULL inputs */
        if (PG_ARGISNULL(0) || PG_ARGISNULL(1))
                PG_RETURN_NULL();

        /* Convert precision text to C string */
        prec = text_to_cstring(prec_text);

        /* Normalize precision string (lowercase, trim whitespace) */
        for (i = 0; prec[i]; i++)
                prec[i] = tolower((unsigned char) prec[i]);

        /* Remove trailing whitespace */
        i = strlen(prec);
        while (i > 0 && isspace((unsigned char) prec[i - 1]))
                prec[--i] = '\0';

        /* Find matching precision unit */
        i = 0;
        while (i < lengthof(trunc_units))
        {
                if (strcmp(prec, trunc_units[i]) == 0)
                        break;
                i++;
        }

        /* Check if precision unit was found */
        if (i >= lengthof(trunc_units))
                ereport(ERROR,
                                (errcode(ERRCODE_INVALID_PARAMETER_VALUE),
                                 errmsg("invalid type name \"%s\"", prec),
                                 errdetail("Valid units are: microseconds, milliseconds, second, minute, hour, day, week, month, year, decade, century, millennium.")));

