        timestamp_val = PG_GETARG_TIMESTAMP(1);

        /* Convert timestamp to pg_tm structure */
        if (timestamp2tm(timestamp_val, NULL, &tm, &fsec, NULL, NULL) != 0)
                ereport(ERROR,
                                (errcode(ERRCODE_DATETIME_VALUE_OUT_OF_RANGE),
                                 errmsg("timestamp out of range")));

