        switch (i)
        {
                case 0:                                         /* microseconds */
                        /* No truncation needed, fsec is already in microseconds */
                        break;
                case 1:                                         /* milliseconds */
                        fsec = (fsec_t) ((int64) (fsec * 1000)) / 1000.0;
                        break;
                case 2:                                         /* second */
                        fsec = 0;
                        break;
                case 3:                                         /* minute */
                        tm.tm_sec = 0;
                        fsec = 0;
                        break;
                case 4:                                         /* hour */
                        tm.tm_min = 0;
                        tm.tm_sec = 0;
                        fsec = 0;
                        break;
                case 5:                                         /* day */
                        tm.tm_hour = 0;
                        tm.tm_min = 0;
                        tm.tm_sec = 0;
                        fsec = 0;
                        break;
                case 6:                                         /* week */
                        {
                                int                     wday = tm.tm_wday;

                                /* Adjust to Monday as first day of week */
                                tm.tm_mday -= (wday + 6) % 7;
                                tm.tm_hour = 0;
                                tm.tm_min = 0;
                                tm.tm_sec = 0;
                                fsec = 0;
                        }
                        break;
                case 7:                                         /* month */
                        tm.tm_mday = 1;
                        tm.tm_hour = 0;
                        tm.tm_min = 0;
                        tm.tm_sec = 0;
                        fsec = 0;
                        break;
                case 8:                                         /* year */
                        tm.tm_mon = 1;
                        tm.tm_mday = 1;
                        tm.tm_hour = 0;
                        tm.tm_min = 0;
                        tm.tm_sec = 0;
                        fsec = 0;
                        break;
                case 9:                                         /* decade */
                        tm.tm_year = (tm.tm_year / 10) * 10;
                        tm.tm_mon = 1;
                        tm.tm_mday = 1;
                        tm.tm_hour = 0;
                        tm.tm_min = 0;
                        tm.tm_sec = 0;
                        fsec = 0;
                        break;
                case 10:                                        /* century */
                        tm.tm_year = (tm.tm_year / 100) * 100;
                        tm.tm_mon = 1;
                        tm.tm_mday = 1;
                        tm.tm_hour = 0;
                        tm.tm_min = 0;
                        tm.tm_sec = 0;
                        fsec = 0;
                        break;
                case 11:                                        /* millennium */
                        tm.tm_year = (tm.tm_year / 1000) * 1000;
                        tm.tm_mon = 1;
                        tm.tm_mday = 1;
                        tm.tm_hour = 0;
                        tm.tm_min = 0;
                        tm.tm_sec = 0;
                        fsec = 0;
                        break;
        }

        /* Convert back to timestamp */
        if (tm2timestamp(&tm, fsec, NULL, &result) != 0)
                ereport(ERROR,
                                (errcode(ERRCODE_DATETIME_VALUE_OUT_OF_RANGE),
                                 errmsg("timestamp out of range")));

        pfree(prec);

        PG_RETURN_TIMESTAMP(result);
}

